def gen(draw):
    n = draw(st.integers(1, 5))
    m = draw(st.integers(1, 5))
    hi = draw(st.sampled_from([3, 10, 20]))
    a = draw(st.lists(st.integers(1, hi), min_size=n, max_size=n))
    b = draw(st.lists(st.integers(1, hi), min_size=m, max_size=m))
    if draw(st.booleans()):
        # all-equal edge case
        v = draw(st.integers(1, hi))
        a = [v] * n
    return f"{n} {m}\n{' '.join(map(str, a))}\n{' '.join(map(str, b))}\n"

